
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ms2_rev_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ms2_rev", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.682539366743134e+00, -4.589760159201837e+00, -4.459781087542203e+00, -4.279785131657651e+00, -4.034641068091583e+00, -3.708642083097873e+00, -3.289643298961389e+00, -2.776502248202341e+00, -2.188054839834862e+00, -1.549954950097457e+00, -9.936055051495816e-01, -6.856538735932840e-01, -6.050353001741531e-01, -5.167875388783831e-01, -3.642442059346189e-01, -2.194172727206537e-01, -1.138198703884384e-01, -4.140924746339030e-02, -9.015224520364757e-03, -1.013953113679643e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


